-- ULUGBEK AI video community + course marketplace schema.
-- Requires db/schema.sql first (app_users table).
-- Not auto-applied. Run only after PostgreSQL is configured.
-- Store media in private object storage; never store raw media bytes in PostgreSQL.
CREATE TABLE IF NOT EXISTS video_posts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, title TEXT NOT NULL DEFAULT '' CHECK (char_length(title) <= 160), description TEXT NOT NULL DEFAULT '' CHECK (char_length(description) <= 3000), media_object_key TEXT NOT NULL, media_content_type TEXT NOT NULL CHECK (media_content_type IN ('video/mp4','video/webm','video/quicktime')), media_size_bytes BIGINT NOT NULL CHECK (media_size_bytes > 0 AND media_size_bytes <= 1073741824), allow_download BOOLEAN NOT NULL DEFAULT false, visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public','followers','private')), moderation_status TEXT NOT NULL DEFAULT 'pending' CHECK (moderation_status IN ('pending','approved','rejected','removed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS video_posts_feed_idx ON video_posts(moderation_status, visibility, created_at DESC);
CREATE INDEX IF NOT EXISTS video_posts_owner_idx ON video_posts(owner_user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS video_reactions (video_id UUID NOT NULL REFERENCES video_posts(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, reaction TEXT NOT NULL DEFAULT 'like' CHECK (reaction IN ('like')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(video_id, user_id));
CREATE TABLE IF NOT EXISTS video_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), video_id UUID NOT NULL REFERENCES video_posts(id) ON DELETE CASCADE, author_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, comment_type TEXT NOT NULL CHECK (comment_type IN ('text','voice','video')), text_content TEXT CHECK (text_content IS NULL OR char_length(text_content) <= 2000), media_object_key TEXT, media_content_type TEXT, media_size_bytes BIGINT CHECK (media_size_bytes IS NULL OR (media_size_bytes > 0 AND media_size_bytes <= 104857600)), moderation_status TEXT NOT NULL DEFAULT 'pending' CHECK (moderation_status IN ('pending','approved','rejected','removed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((comment_type = 'text' AND text_content IS NOT NULL AND media_object_key IS NULL) OR (comment_type IN ('voice','video') AND media_object_key IS NOT NULL AND media_content_type IS NOT NULL)));
CREATE INDEX IF NOT EXISTS video_comments_video_idx ON video_comments(video_id, created_at);
CREATE TABLE IF NOT EXISTS video_live_rooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), host_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, room_status TEXT NOT NULL DEFAULT 'waiting' CHECK (room_status IN ('waiting','active','ended','blocked')), provider_room_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), started_at TIMESTAMPTZ, ended_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS video_live_rooms_host_idx ON video_live_rooms(host_user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS courses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), instructor_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, title TEXT NOT NULL CHECK (char_length(title) BETWEEN 3 AND 120), category TEXT NOT NULL CHECK (char_length(category) <= 80), description TEXT NOT NULL CHECK (char_length(description) BETWEEN 10 AND 5000), price_minor BIGINT NOT NULL CHECK (price_minor >= 0), currency CHAR(3) NOT NULL DEFAULT 'USD', status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_review','published','rejected','archived')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS courses_catalog_idx ON courses(status, category, published_at DESC);
CREATE INDEX IF NOT EXISTS courses_instructor_idx ON courses(instructor_user_id, updated_at DESC);
CREATE TABLE IF NOT EXISTS course_lessons (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 160), description TEXT NOT NULL DEFAULT '' CHECK (char_length(description) <= 2000), position INTEGER NOT NULL CHECK (position >= 0), media_object_key TEXT, duration_seconds INTEGER CHECK (duration_seconds IS NULL OR duration_seconds BETWEEN 1 AND 86400), preview_allowed BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(course_id, position));
CREATE TABLE IF NOT EXISTS course_enrollments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_id UUID NOT NULL REFERENCES courses(id) ON DELETE RESTRICT, student_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, enrollment_status TEXT NOT NULL DEFAULT 'pending_payment' CHECK (enrollment_status IN ('pending_payment','active','refunded','cancelled')), payment_provider TEXT, provider_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(course_id, student_user_id));
CREATE INDEX IF NOT EXISTS course_enrollments_student_idx ON course_enrollments(student_user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS course_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, reviewer_user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5), review_text TEXT NOT NULL DEFAULT '' CHECK (char_length(review_text) <= 2000), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(course_id, reviewer_user_id));
